fn extract_literal_with_op(expr: &SQLExpr) -> Option<(&SQLValue, Option<&SQLUnaryOperator>)> {
    match expr {
        SQLExpr::Value(ValueWithSpan { value, .. }) => Some((value, None)),
        SQLExpr::UnaryOp { op, expr } => match expr.as_ref() {
            SQLExpr::Value(ValueWithSpan { value, .. }) => Some((value, Some(op))),
            _ => None,
        },
        _ => None,
    }
}

/// Resolve the Polars dtype associated with a temporal typed literal (eg: `DATE '2020-01-01'`,
/// `TIME '01:02:03'`, `TIMESTAMP(3) '2020-01-01 01:02:03'`), validating that the string value
/// is a well-formed ISO literal for the given type.
fn resolve_typed_literal_dtype(data_type: &SQLDataType, value: &str) -> PolarsResult<DataType> {
    match data_type {
        SQLDataType::Date => {
            if is_iso_date(value) {
                Ok(DataType::Date)
            } else {
                polars_bail!(SQLSyntax: "invalid DATE literal '{}'", value)
            }
        },
        SQLDataType::Time(_, TimezoneInfo::None) => {
            if is_iso_time(value) {
                Ok(DataType::Time)
            } else {
                polars_bail!(SQLSyntax: "invalid TIME literal '{}'", value)
            }
        },
        SQLDataType::Timestamp(_, TimezoneInfo::None) | SQLDataType::Datetime(_) => {
            if is_iso_datetime(value) {
                map_sql_dtype_to_polars(data_type)
            } else {
                let fn_name = match data_type {
                    SQLDataType::Timestamp(_, _) => "TIMESTAMP",
                    _ => "DATETIME",
                };
                polars_bail!(SQLSyntax: "invalid {} literal '{}'", fn_name, value)
            }
        },
        _ => {
            polars_bail!(SQLInterface: "typed literal should be one of DATE, DATETIME, TIME, or TIMESTAMP (found {})", data_type)
        },
    }
}

/// Ensure that all the collected `dtypes` are identical, returning the common dtype (if any).
/// If the dtypes are inconsistent a `SQLInterface` error is raised; `desc` is used to prefix
/// the error message (eg: "array literal ").
fn resolve_common_dtype(dtypes: &[DataType], desc: &str) -> PolarsResult<Option<DataType>> {
    let mut iter = dtypes.iter();
    let Some(first) = iter.next() else {
        return Ok(None);
    };
    for dtype in iter {
        if dtype != first {
            polars_bail!(
                SQLInterface: "{}expected consistent dtypes (found {:?} and {:?})", desc, first, dtype
            );
        }
    }
    Ok(Some(first.clone()))
}

/// Cast a series of scalar literals (typically strings gathered from typed/cast array elements)
/// to the requested `dtype`. String values targeting temporal dtypes are parsed accordingly.
fn cast_literal_series(s: Series, dtype: &DataType) -> PolarsResult<Series> {
    if s.dtype() == dtype {
        return Ok(s);
    }
    if matches!(s.dtype(), DataType::String) {
        let name = s.name().clone();
        let parse_expr = match dtype {
            #[cfg(feature = "dtype-date")]
            DataType::Date => Some(col(name.clone()).cast(DataType::Date)),
            #[cfg(feature = "dtype-time")]
            DataType::Time => Some(col(name.clone()).str().to_time(StrptimeOptions {
                strict: true,
                ..Default::default()
            })),
            #[cfg(feature = "dtype-datetime")]
            DataType::Datetime(tu, tz) => Some(col(name.clone()).str().to_datetime(
                Some(*tu),
                tz.clone(),
                StrptimeOptions {
                    strict: true,
                    ..Default::default()
                },
                lit("latest"),
            )),
            _ => None,
        };
        if let Some(expr) = parse_expr {
            let df = DataFrame::new(vec![s.into_column()])?;
            let out = df.lazy().select([expr]).collect()?;
            return Ok(out.select_at_idx(0).unwrap().as_materialized_series().clone());
        }
    }
    s.strict_cast(dtype)
}

